  function toLocalDateTime(value){if(!value)return '';const date=new Date(value);if(Number.isNaN(date.getTime()))return '';const local=new Date(date.getTime()-date.getTimezoneOffset()*60000);return local.toISOString().slice(0,16);}
  function publicUrl(path){return path?new URL(path,location.origin).href:'';}
  function selectedPublicColumns(){return Array.from(document.querySelectorAll('[data-public-column]:checked')).map(input=>input.value);}
  function renderPublicColumns(columns,selected){
    const chosen=new Set((selected||[]).map(String));
    $('dbPublicColumns').innerHTML=(columns||[]).map(name=>`<label class="db-public-column"><input type="checkbox" data-public-column value="${esc(name)}" ${chosen.has(String(name))?'checked':''}><span>${esc(name)}</span></label>`).join('')||'<div class="db-help">ยังไม่มีคอลัมน์ที่เผยแพร่ได้</div>';
  }
  function renderPublicQr(url){
    $('dbPublicQr').innerHTML='';if(!url||!window.QRCode)return;
    new QRCode($('dbPublicQr'),{text:url,width:190,height:190,colorDark:'#10243e',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});
  }
  function applyPublicSettings(settings){
    state.publicShare=settings||{};const url=publicUrl(settings.publicPath);
    $('dbPublicShareTitle').textContent=`ลิงก์สาธารณะ: ${settings.title||'Dashboard'}`;
    $('dbPublicEnabled').checked=!!settings.enabled;$('dbPublicExpiresAt').value=toLocalDateTime(settings.expiresAt);$('dbPublicRequirePin').checked=!!settings.hasPin;$('dbPublicPin').value='';$('dbPublicPin').disabled=!settings.hasPin;$('dbPublicAllowExport').checked=!!settings.allowExport;
    renderPublicColumns(settings.columns||[],settings.visibleColumns||[]);$('dbPublicLink').value=url;$('dbPublicCopyLink').disabled=!url;$('dbPublicOpenLink').disabled=!url;$('dbPublicRevoke').disabled=!settings.enabled;$('dbPublicRegenerate').disabled=!settings.enabled;
    const access=settings.accessCount?` เปิดดู ${Number(settings.accessCount).toLocaleString('th-TH')} ครั้ง${settings.lastAccessAt?` • ล่าสุด ${formatDate(settings.lastAccessAt)}`:''}`:'';
    $('dbPublicInfo').textContent=settings.enabled?`เปิดใช้งาน${settings.hasPin?' • มี PIN':''}${settings.expiresAt?` • หมดอายุ ${formatDate(settings.expiresAt)}`:''}${access}`:`ยังไม่ได้เปิดลิงก์สาธารณะ${settings.status!=='active'?' • Dashboard ต้องมีสถานะ “ใช้งาน”':''}`;
    renderPublicQr(url);
  }
  async function openPublicShare(id){
    try{
      $('dbPublicShareModal').classList.add('show');$('dbPublicShareTitle').textContent='กำลังโหลดการตั้งค่าลิงก์สาธารณะ...';$('dbPublicColumns').innerHTML='<div class="db-loading"><strong>กำลังตรวจสิทธิ์...</strong></div>';
      const result=await gas('getDashboardPublicShareSettingsV7134',state.token,id);if(!result||!result.success)throw new Error(result&&result.message||'โหลดการตั้งค่าไม่สำเร็จ');applyPublicSettings(result.settings);
    }catch(error){$('dbPublicShareModal').classList.remove('show');notify('error','เปิดการตั้งค่าลิงก์ไม่สำเร็จ',error.message);}
  }
  async function savePublicShare(action){
    if(!state.publicShare||!state.publicShare.dashboardId)return;
    if(action==='revoke'&&!await confirmAction('ปิดลิงก์สาธารณะ?','ผู้ที่มีลิงก์เดิมจะเปิด Dashboard นี้ไม่ได้ทันที'))return;
    if(action==='regenerate'&&!await confirmAction('สร้างลิงก์ใหม่?','ลิงก์เดิมจะถูกยกเลิกทันที และต้องส่งลิงก์ใหม่ให้ผู้ใช้งาน'))return;
    const payload={action:action||'save',enabled:$('dbPublicEnabled').checked,expiresAt:$('dbPublicExpiresAt').value?new Date($('dbPublicExpiresAt').value).toISOString():'',requirePin:$('dbPublicRequirePin').checked,pin:$('dbPublicPin').value,allowExport:$('dbPublicAllowExport').checked,visibleColumns:selectedPublicColumns()};
    const buttons=[$('dbPublicSave'),$('dbPublicRegenerate'),$('dbPublicRevoke')];buttons.forEach(button=>button.disabled=true);
    try{const result=await gas('saveDashboardPublicShareV7134',state.token,state.publicShare.dashboardId,payload);if(!result||!result.success)throw new Error(result&&result.message||'บันทึกไม่สำเร็จ');applyPublicSettings(result.settings);notify('success',action==='revoke'?'ปิดลิงก์แล้ว':action==='regenerate'?'สร้างลิงก์ใหม่แล้ว':'บันทึกการตั้งค่าแล้ว',result.settings.publicPath?'พร้อมส่งลิงก์ให้ผู้ชม':'ลิงก์สาธารณะยังปิดอยู่');}
    catch(error){notify('error','จัดการลิงก์ไม่สำเร็จ',error.message);applyPublicSettings(state.publicShare);}
  }
  async function copyPublicLink(){const value=$('dbPublicLink').value;if(!value)return;try{await navigator.clipboard.writeText(value);notify('success','คัดลอกลิงก์แล้ว','');}catch(_error){$('dbPublicLink').select();document.execCommand('copy');notify('success','คัดลอกลิงก์แล้ว','');}}

  function renderSyncSettings(result){
    const settings=result.settings||{};const source=result.source||{};state.syncSettings=settings;
    $('dbSyncSource').innerHTML=`<div><strong>${esc(source.sheetName||'Google Sheets')}</strong><small>${esc(source.url||'ไม่พบ URL ต้นทาง')} • แถวหัวตาราง ${Number(source.headerRow||1).toLocaleString('th-TH')}</small></div><span class="db-status">${Number(source.rowCount||0).toLocaleString('th-TH')} แถวล่าสุด</span>`;
    $('dbSyncEnabled').checked=!!settings.enabled;$('dbSyncInterval').value=String(settings.intervalMinutes||60);$('dbSyncNotifyFailure').checked=settings.notifyOnFailure!==false;
    const status=$('dbSyncStatus');status.className='db-sync-status '+(settings.lastStatus||'');
    if(settings.lastSyncAt){status.innerHTML=`<strong>${settings.lastStatus==='success'?'ซิงก์ล่าสุดสำเร็จ':'ซิงก์ล่าสุดไม่สำเร็จ'}</strong><br>${esc(settings.lastMessage||'')}<br><small>${formatDate(settings.lastSyncAt)}${settings.enabled&&settings.nextSyncAt?` • รอบถัดไป ${formatDate(settings.nextSyncAt)}`:''}</small>`;}
    else status.innerHTML=`<strong>ยังไม่เคยซิงก์จากต้นทาง</strong><br><small>${settings.enabled&&settings.nextSyncAt?`รอบแรก ${formatDate(settings.nextSyncAt)}`:'กด “ซิงก์ตอนนี้” เพื่อทดสอบแหล่งข้อมูลก่อนเปิด Scheduled Sync'}</small>`;
    const history=result.history||[];$('dbSyncHistory').innerHTML=history.length?history.map(item=>`<article class="db-sync-history-item ${item.status==='success'?'':'failed'}"><i class="bi ${item.status==='success'?'bi-check-circle-fill':'bi-exclamation-circle-fill'}"></i><div><strong>${item.mode==='scheduled'?'Scheduled Sync':'Manual Sync'} • ${item.status==='success'?`${Number(item.rowCount||0).toLocaleString('th-TH')} แถว`:'ไม่สำเร็จ'}</strong><small>${esc(item.message||'')}</small></div><time>${formatDate(item.createdAt)}</time></article>`).join(''):'<div class="db-empty"><span>ยังไม่มีประวัติการซิงก์</span></div>';
    $('dbSyncRunNow').disabled=!result.supported;$('dbSyncSave').disabled=!result.supported;$('dbSyncEnabled').disabled=!result.supported;$('dbSyncInterval').disabled=!result.supported;$('dbSyncNotifyFailure').disabled=!result.supported;
  }
  async function loadSyncSettings(dashboardId){const result=await gas('getDashboardSyncSettingsV7139',state.token,dashboardId);if(!result||!result.success)throw new Error(result&&result.message||'โหลดการตั้งค่าซิงก์ไม่สำเร็จ');renderSyncSettings(result);return result;}
  async function openSyncModal(dashboardId){
    try{$('dbSyncModal').classList.add('show');$('dbSyncStatus').className='db-sync-status running';$('dbSyncStatus').textContent='กำลังโหลดสถานะการซิงก์...';$('dbSyncHistory').innerHTML='';await loadSyncSettings(dashboardId);}
    catch(error){$('dbSyncModal').classList.remove('show');notify('error','เปิด Data Sync ไม่สำเร็จ',error.message);}
  }
  async function runGoogleSync(){
    if(!state.project||!state.project.id)return;$('dbSyncRunNow').disabled=true;$('dbSyncSave').disabled=true;$('dbSyncStatus').className='db-sync-status running';$('dbSyncStatus').innerHTML='<strong>กำลังอ่าน Google Sheet และสร้าง Dataset ใหม่...</strong><br><small>ข้อมูลเดิมจะยังแสดงต่อจนกว่าการซิงก์เสร็จสมบูรณ์</small>';
    try{const result=await gas('syncDashboardGoogleSourceV7139',state.token,state.project.id);if(!result||!result.success)throw new Error(result&&result.message||'ซิงก์ไม่สำเร็จ');await openProject(state.project.id,false);await loadSyncSettings(state.project.id);notify('success','ซิงก์ข้อมูลสำเร็จ',`${Number(result.rowCount||0).toLocaleString('th-TH')} แถว • Dashboard และ Public Link ใช้ข้อมูลชุดใหม่แล้ว`);}
    catch(error){await loadSyncSettings(state.project.id).catch(()=>{});notify('error','ซิงก์ Google Sheet ไม่สำเร็จ',error.message);}
    finally{$('dbSyncRunNow').disabled=false;$('dbSyncSave').disabled=false;}
  }
  async function saveGoogleSyncSettings(){
    if(!state.project||!state.project.id)return;const payload={enabled:$('dbSyncEnabled').checked,intervalMinutes:Number($('dbSyncInterval').value||60),notifyOnFailure:$('dbSyncNotifyFailure').checked};$('dbSyncSave').disabled=true;
    try{const result=await gas('saveDashboardSyncSettingsV7139',state.token,state.project.id,payload);if(!result||!result.success)throw new Error(result&&result.message||'บันทึกไม่สำเร็จ');await loadSyncSettings(state.project.id);notify('success','บันทึก Scheduled Sync แล้ว',payload.enabled?'ระบบจะซิงก์ตามรอบที่เลือก':'ปิดการซิงก์อัตโนมัติแล้ว');}
    catch(error){notify('error','บันทึก Scheduled Sync ไม่สำเร็จ',error.message);}
    finally{$('dbSyncSave').disabled=false;}
  }

  function moveWidgetByStep(id,delta){
    const widgets=state.project.config.widgets.slice().sort((a,b)=>(a.order||0)-(b.order||0));
    const index=widgets.findIndex(widget=>String(widget.id)===String(id));
    const target=Math.max(0,Math.min(widgets.length-1,index+Number(delta||0)));
    if(index<0||target===index)return;
    const item=widgets.splice(index,1)[0];widgets.splice(target,0,item);widgets.forEach((widget,order)=>{widget.order=order;});
    state.project.config.widgets=widgets;renderEditor();
  }

  document.addEventListener('click',event=>{
    const view=event.target.closest('[data-project-view]');if(view)return openProject(view.dataset.projectView,false);
    const edit=event.target.closest('[data-project-edit]');if(edit)return openProject(edit.dataset.projectEdit,true);
    const share=event.target.closest('[data-project-share]');if(share)return openProjectForShare(share.dataset.projectShare);
    const publicShare=event.target.closest('[data-project-public]');if(publicShare)return openPublicShare(publicShare.dataset.projectPublic);
    const copy=event.target.closest('[data-project-copy]');if(copy)return duplicateProject(copy.dataset.projectCopy);
    const del=event.target.closest('[data-project-delete]');if(del)return deleteProject(del.dataset.projectDelete);
    const scope=event.target.closest('[data-list-scope]');if(scope){state.scope=scope.dataset.listScope;renderProjects();return;}
    const source=event.target.closest('[data-source]');if(source){document.querySelectorAll('[data-source]').forEach(el=>el.classList.toggle('active',el===source));document.querySelectorAll('[data-source-pane]').forEach(el=>el.classList.toggle('active',el.dataset.sourcePane===source.dataset.source));return;}
    const theme=event.target.closest('[data-dashboard-theme]');if(theme){state.project.config=normalizeConfig(state.project.config);state.project.config.theme=theme.dataset.dashboardTheme;renderEditor();return;}
    const density=event.target.closest('[data-dashboard-density]');if(density){state.project.config=normalizeConfig(state.project.config);state.project.config.density=density.dataset.dashboardDensity;renderEditor();return;}
    const layout=event.target.closest('[data-smart-layout]');if(layout){smartLayout(layout.dataset.smartLayout);return;}
    const device=event.target.closest('[data-preview-device]');if(device){state.previewDevice=device.dataset.previewDevice;$('dbEditorStage').dataset.previewDevice=state.previewDevice;document.querySelectorAll('[data-preview-device]').forEach(button=>button.classList.toggle('active',button===device));return;}
    const copilotPrompt=event.target.closest('[data-copilot-prompt]');if(copilotPrompt){$('dbCopilotPrompt').value=copilotPrompt.dataset.copilotPrompt;$('dbCopilotPrompt').focus();return;}
    const removeCross=event.target.closest('[data-cross-filter-remove]');if(removeCross){state.crossFilters.splice(Number(removeCross.dataset.crossFilterRemove),1);renderProjectCanvas();return;}
    if(event.target.closest('[data-cross-filter-clear]')){state.crossFilters=[];renderProjectCanvas();return;}
    const add=event.target.closest('[data-add-widget]');if(add)return openWidget(add.dataset.addWidget);
    const stepMove=event.target.closest('[data-widget-move-step]');if(stepMove){moveWidgetByStep(stepMove.dataset.widgetId,stepMove.dataset.widgetMoveStep);return;}
    const editWidget=event.target.closest('[data-widget-edit]');if(editWidget)return openWidget('',state.project.config.widgets.find(w=>w.id===editWidget.dataset.widgetEdit));
    const duplicateWidget=event.target.closest('[data-widget-duplicate]');if(duplicateWidget){const sourceWidget=state.project.config.widgets.find(w=>w.id===duplicateWidget.dataset.widgetDuplicate);if(sourceWidget){state.project.config.widgets.push({...sourceWidget,id:crypto.randomUUID(),title:sourceWidget.title+' (สำเนา)',order:state.project.config.widgets.length});renderEditor();}return;}
    const deleteWidget=event.target.closest('[data-widget-delete]');if(deleteWidget){state.project.config.widgets=state.project.config.widgets.filter(w=>w.id!==deleteWidget.dataset.widgetDelete);renderEditor();return;}
    const deleteFilter=event.target.closest('[data-filter-delete]');if(deleteFilter){state.project.config.filters.splice(Number(deleteFilter.dataset.filterDelete),1);renderEditor();return;}
    const close=event.target.closest('[data-close-modal]');if(close)$(close.dataset.closeModal).classList.remove('show');
  });
  document.addEventListener('change',event=>{const enable=event.target.dataset.schemaEnable;if(enable!=null){state.schema[Number(enable)].enabled=event.target.checked;renderSchema();return;}const type=event.target.dataset.schemaType;if(type!=null)state.schema[Number(type)].type=event.target.value;const decimals=event.target.dataset.schemaDecimals;if(decimals!=null)state.schema[Number(decimals)].decimals=Number(event.target.value||0);const filter=event.target.dataset.viewFilter;if(filter!=null)renderProjectCanvas();});
  $('dbPublicRequirePin').addEventListener('change',event=>{$('dbPublicPin').disabled=!event.target.checked;if(event.target.checked)$('dbPublicPin').focus();});
  document.addEventListener('input',event=>{const name=event.target.dataset.schemaName;if(name!=null)state.schema[Number(name)].name=event.target.value;if(['dbSearch','dbStatusFilter','dbOwnerFilter'].includes(event.target.id))renderProjects();if(event.target.dataset.viewFilter!=null){clearTimeout(state.filterTimer);state.filterTimer=setTimeout(renderProjectCanvas,180);}});
  $('dbCreateBtn').addEventListener('click',()=>openWizard());$('dbFile').addEventListener('change',handleFile);$('dbSheet').addEventListener('change',readWorkbookSheet);$('dbHeaderRow').addEventListener('change',readWorkbookSheet);$('dbImportGoogleBtn').addEventListener('click',importGoogle);$('dbNextStep').addEventListener('click',()=>{try{validateStep();state.step=Math.min(5,state.step+1);refreshWizard();}catch(error){notify('warning','ยังไปต่อไม่ได้',error.message);}});$('dbPrevStep').addEventListener('click',()=>{state.step=Math.max(1,state.step-1);refreshWizard();});$('dbCancelWizard').addEventListener('click',()=>showView('dbListView'));$('dbSaveProject').addEventListener('click',saveProject);$('dbConfirmWidget').addEventListener('click',saveWidget);$('dbAiSuggestBtn').addEventListener('click',aiSuggest);$('dbApplyTemplateBtn').addEventListener('click',applySmartTemplate);$('dbCopilotRunBtn').addEventListener('click',runPrivateCopilot);$('dbResetLayoutBtn').addEventListener('click',()=>{state.project.config=defaultConfig($('dbTemplate').value);renderEditor();});$('dbPreviewBtn').addEventListener('click',()=>{state.project.rows=state.rows;openProjectPreview();});$('dbBackList').addEventListener('click',()=>showView('dbListView'));$('dbEditCurrent').addEventListener('click',()=>openWizard({...state.project,rows:state.rows,schema:state.schema,source:state.project.source||{}}));$('dbSyncCurrent').addEventListener('click',()=>state.project&&state.project.id&&openSyncModal(state.project.id));$('dbSyncRunNow').addEventListener('click',runGoogleSync);$('dbSyncSave').addEventListener('click',saveGoogleSyncSettings);$('dbRefreshDashboard').addEventListener('click',()=>state.project&&state.project.id&&openProject(state.project.id,false));$('dbExportCurrent').addEventListener('click',()=>{const rows=HAOSDashboardRenderer.filteredRows(state.rows,allViewerFilters());const fields=state.schema.filter(column=>column.enabled!==false).map(column=>column.name);HAOSDashboardRenderer.downloadCsv(rows,fields,state.project.title||'dashboard-data');});$('dbRefreshBtn').addEventListener('click',()=>location.reload());
  $('dbPublicShareCurrent').addEventListener('click',()=>state.project&&state.project.id&&openPublicShare(state.project.id));$('dbPublicSave').addEventListener('click',()=>savePublicShare('save'));$('dbPublicRegenerate').addEventListener('click',()=>savePublicShare('regenerate'));$('dbPublicRevoke').addEventListener('click',()=>savePublicShare('revoke'));$('dbPublicCopyLink').addEventListener('click',copyPublicLink);$('dbPublicOpenLink').addEventListener('click',()=>{const url=$('dbPublicLink').value;if(url)window.open(url,'_blank','noopener');});$('dbPublicSelectAll').addEventListener('click',()=>document.querySelectorAll('[data-public-column]').forEach(input=>{input.checked=true;}));$('dbPublicClearColumns').addEventListener('click',()=>document.querySelectorAll('[data-public-column]').forEach(input=>{input.checked=false;}));
  $('dbViewerFilters').addEventListener('haos:dashboard-reset-interactions',()=>{if(state.crossFilters.length){state.crossFilters=[];renderProjectCanvas();}});
  $('dbAddFilterBtn').addEventListener('click',()=>{const field=$('dbFilterField').value;if(!field)return;const type=$('dbFilterType').value;state.project.config.filters=state.project.config.filters||[];state.project.config.filters.push({field,type,title:field});renderEditor();});
  document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.db-modal.show').forEach(modal=>modal.classList.remove('show'));});
  function openProjectPreview(){const preview=window.open('','_blank');if(!preview)return notify('warning','เบราว์เซอร์ปิดกั้น Popup','กรุณาอนุญาต Popup แล้วลองใหม่');const previewRows=HAOSDashboardData.applySchema(state.rows,state.schema).slice(0,5000);preview.document.write(`<title>${esc(state.project.title||'Dashboard Preview')}</title><meta name="viewport" content="width=device-width,initial-scale=1"><link href="/assets/css/dashboard-builder.css?v=70139" rel="stylesheet"><link href="/assets/css/dashboard-builder-enhancements.css?v=70139" rel="stylesheet"><link href="/assets/css/dashboard-viewer.css?v=70139" rel="stylesheet"><body><main class="db-shell"><section class="db-panel"><div class="db-toolbar"><strong>${esc(state.project.title||'Dashboard Preview')}</strong><span class="db-status">ตัวอย่างสูงสุด 5,000 แถว</span></div><div id="preview" class="db-dashboard db-viewer-canvas" style="margin:18px"></div></section></main><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"><\/script><script src="/assets/js/dashboard-builder/renderer.js?v=70139"><\/script><script>addEventListener('load',()=>HAOSDashboardRenderer.render(document.getElementById('preview'),${JSON.stringify(state.project).replace(/</g,'\\u003c')},${JSON.stringify(previewRows).replace(/</g,'\\u003c')},{interactive:{crossFilter:true,drilldown:true}}));<\/script>`);preview.document.close();}
  boot();console.info(`HAOS ${VERSION} loaded`);
